class RecentCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.keys = []
        self.data = {}

    def get(self, key):
        if key not in self.data:
            return None
        # Move key to the end of self.keys
        self.keys.append(key)
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            self.keys.remove(key)
        elif self.capacity == len(self.data):
            # Remove the least recently used key from self.keys and self.data
            self.keys.pop(0)
            self.data.pop(key)
        self.keys.append(key)
